"use client"

import animation from "react-useanimations/lib/shuffle"

import { UseAnimation, type UseAnimationProps } from "@/components/use-animation"

// "Shuffle" from https://useanimations.com (MIT): https://useanimations.com/icons/shuffle
export function AnimatedShuffle(
  props: Omit<UseAnimationProps, "animationData">
) {
  return (
    <UseAnimation
      animationData={animation.animationData}
      interaction="click-replay"
      {...props}
    />
  )
}
